package Tv3.Controller;
import Tv3.View.LopChiTietPage;import MainPage.View.Workspace;import MainPage.Controller.PageTasks;import Model.*;import Service.*;import java.awt.Component;import java.util.*;
public class LopChiTietPageBridge {
 public static void open(Component owner,int b,int id){LopChiTietPage v=new LopChiTietPage();v.title("CHI TIẾT LỚP #"+id,"Đang tải...");v.columns("Mã học viên","Tên học viên","Mã đăng ký","Trạng thái","Ngày bắt đầu");v.action("Hồ sơ học viên",()->{int r=v.selected();if(r>=0)Tv2.Controller.HoSoHocVienController.openWindow(v,b,(int)v.value(r,0));});Workspace.window(owner,"Chi tiết lớp",v);PageTasks.run(v,()->{var l=new LopHocService().getByMaLop(b,id);PageTasks.require(l!=null,"Không tìm thấy lớp");var hs=new HocVienService().selectAll(b);var map=new HashMap<Integer,String>();hs.forEach(h->map.put(h.getMaHocVien(),h.getHoTen()));var regs=new DangKyHocService().getByMaLop(b,id);return new Object[]{l,regs.stream().map(x->new Object[]{x.getMaHocVien(),map.get(x.getMaHocVien()),x.getMaDangKy(),x.getTrangThai(),x.getNgayBatDau()}).toArray(Object[][]::new),regs.stream().filter(x->"DANG_HOC".equals(x.getTrangThai())).map(DangKyHocModel::getMaHocVien).distinct().count()};},d->{LopHocModel l=(LopHocModel)d[0];v.title(l.getTenLop(),"Sĩ số đang học: "+d[2]+" / "+PageTasks.text(l.getSiSoToiDa())+" | Giáo viên #"+PageTasks.text(l.getMaGiaoVien()));v.rows((Object[][])d[1]);v.status("Bắt đầu: "+l.getNgayBatDau()+" | Học phí: "+l.getHocPhiMacDinh());});}
}
